import React from 'react';
import { Server, PlayCircle, HeartPulse, Gauge, Zap, AlertTriangle, Calendar, Award, TrendingUp } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const EnhancedKPICards = ({ summary }) => {
  const navigate = useNavigate();

  const totalAssets = summary?.totalAssets || 20;
  const running = summary?.running || 16;
  const health = 96;
  const todayProd = 14250;
  const energy = 1245;
  const alerts = summary?.highCriticality || 3;
  const maintenance = summary?.maintenance || 5;

  const cards = [
    {
      title: 'Total Assets',
      value: totalAssets,
      unit: 'Looms',
      trend: '↑ 5% this month',
      trendPositive: true,
      sub: 'Across 6 Factory Hubs',
      icon: Server,
      accent: '#2563EB',
      bg: '#EFF6FF',
      route: '/assets',
    },
    {
      title: 'Running Machines',
      value: running,
      unit: `(${Math.round((running / totalAssets) * 100)}%)`,
      trend: `${Math.round((running / totalAssets) * 100)}% Operational Rate`,
      trendPositive: true,
      sub: 'Active Production Looms',
      icon: PlayCircle,
      accent: '#22C55E',
      bg: '#DCFCE7',
      route: '/assets',
    },
    {
      title: 'Machine Health Index',
      value: `${health}%`,
      unit: 'Excellent',
      trend: 'AI Risk Level: Minimal',
      trendPositive: true,
      sub: 'Predictive RUL Model Active',
      icon: HeartPulse,
      accent: '#06B6D4',
      bg: '#ECFEFF',
      route: '/ai-intelligence',
    },
    {
      title: "Today's Production",
      value: `${todayProd.toLocaleString()}`,
      unit: 'Meters',
      trend: 'Target: 16,000 m (89%)',
      trendPositive: true,
      sub: 'Fabric Weaving Yield',
      icon: Gauge,
      accent: '#4F46E5',
      bg: '#EEF2FF',
      route: '/analytics',
    },
    {
      title: 'Energy Consumption',
      value: `${energy.toLocaleString()}`,
      unit: 'kWh',
      trend: '0.42 kWh / meter rate',
      trendPositive: true,
      sub: 'Eco-Rating Grade A+',
      icon: Zap,
      accent: '#10B981',
      bg: '#ECFDF5',
      route: '/analytics',
    },
    {
      title: 'Critical Alerts',
      value: alerts,
      unit: 'Active',
      trend: 'Action Required Promptly',
      trendPositive: false,
      sub: 'High Tension & Thermal',
      icon: AlertTriangle,
      accent: '#EF4444',
      bg: '#FEF2F2',
      route: '/alerts',
    },
    {
      title: 'Upcoming Maintenance',
      value: maintenance,
      unit: 'Scheduled',
      trend: 'Next: LOOM-201 in 48h',
      trendPositive: true,
      sub: 'Preventive Work Orders',
      icon: Calendar,
      accent: '#F97316',
      bg: '#FFF7ED',
      route: '/maintenance',
    },
    {
      title: 'AI Intelligence Score',
      value: '99.4%',
      unit: 'Accuracy',
      trend: 'RUL Failure Prediction Matrix',
      trendPositive: true,
      sub: 'Machine Learning Model',
      icon: Award,
      accent: '#8B5CF6',
      bg: '#F5F3FF',
      route: '/ai-intelligence',
    },
  ];

  return (
    <div
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))',
        gap: '1.25rem',
        marginBottom: '1.75rem',
      }}
    >
      {cards.map((c, idx) => {
        const Icon = c.icon;
        return (
          <div
            key={idx}
            onClick={() => navigate(c.route)}
            style={{
              background: c.bg,
              borderRadius: '12px',
              padding: '1.25rem',
              border: `1px solid ${c.accent}30`,
              cursor: 'pointer',
              transition: 'all 0.2s ease',
              display: 'flex',
              flexDirection: 'column',
              justify: 'space-between',
              boxShadow: '0 4px 15px rgba(0,0,0,0.03)',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translateY(-3px)';
              e.currentTarget.style.borderColor = c.accent;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'none';
              e.currentTarget.style.borderColor = `${c.accent}30`;
            }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.75rem' }}>
              <span style={{ fontSize: '0.8rem', fontWeight: '800', color: '#475569' }}>{c.title}</span>
              <div
                style={{
                  width: '36px',
                  height: '36px',
                  borderRadius: '10px',
                  background: '#ffffff',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: c.accent,
                  flexShrink: 0,
                  boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
                }}
              >
                <Icon size={20} />
              </div>
            </div>

            <div>
              <div style={{ fontSize: '1.7rem', fontWeight: '900', color: '#0F172A', display: 'flex', alignItems: 'baseline', gap: '0.4rem' }}>
                {c.value}
                <span style={{ fontSize: '0.8rem', fontWeight: '700', color: '#64748B' }}>{c.unit}</span>
              </div>
              <div
                style={{
                  fontSize: '0.75rem',
                  color: c.accent,
                  fontWeight: '800',
                  marginTop: '4px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.25rem',
                }}
              >
                <TrendingUp size={12} /> {c.trend}
              </div>
            </div>

            <div
              style={{
                fontSize: '0.72rem',
                color: '#64748B',
                marginTop: '0.85rem',
                paddingTop: '0.6rem',
                borderTop: `1px solid ${c.accent}20`,
                fontWeight: '700',
              }}
            >
              {c.sub}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default EnhancedKPICards;
